import{A as t}from"./BRJxqex9.js";import{b as e,h as o,i as s,k as i,C as c}from"./msPo4OYS.js";const r={class:"page"},d={__name:"privacy",setup(n){return(l,a)=>(c(),o("div",r,[a[0]||(a[0]=s('<section class="hero" data-v-46070531><div class="hero-bg" data-v-46070531></div><div class="hero-content" data-v-46070531><span class="tag" data-v-46070531>Legal</span><h1 class="title" data-v-46070531>Privacy <span class="accent" data-v-46070531>Policy</span></h1><p class="sub" data-v-46070531>Last updated: May 2025</p></div></section><main class="wrap" data-v-46070531><div class="doc" data-v-46070531><section class="doc-section" data-v-46070531><h2 data-v-46070531>1. Information We Collect</h2><p data-v-46070531>When you create an account, we collect your name and email address. If you sign in with a third-party provider (e.g. Google), we receive only the profile information that provider shares with us.</p><p data-v-46070531>We also collect usage data such as watch history and library saves — solely to provide the features you use.</p></section><section class="doc-section" data-v-46070531><h2 data-v-46070531>2. How We Use Your Information</h2><ul data-v-46070531><li data-v-46070531>To provide and improve the platform</li><li data-v-46070531>To personalize your experience (watch history, library)</li><li data-v-46070531>To communicate service updates or respond to your inquiries</li><li data-v-46070531>We do <strong data-v-46070531>not</strong> sell your data to third parties</li></ul></section><section class="doc-section" data-v-46070531><h2 data-v-46070531>3. Cookies</h2><p data-v-46070531>We use essential cookies to keep you logged in and remember your preferences. We do not use advertising cookies or third-party tracking cookies.</p></section><section class="doc-section" data-v-46070531><h2 data-v-46070531>4. Third-Party Services</h2><p data-v-46070531>Salidumay uses TMDB for film metadata and third-party embed players for streaming. These services have their own privacy policies — we encourage you to review them. We do not control what data those embed providers collect.</p></section><section class="doc-section" data-v-46070531><h2 data-v-46070531>5. Data Retention</h2><p data-v-46070531>We retain your account data for as long as your account is active. You can request deletion of your account and all associated data at any time by contacting us.</p></section><section class="doc-section" data-v-46070531><h2 data-v-46070531>6. Your Rights</h2><p data-v-46070531>You have the right to access, correct, or delete your personal data. To exercise these rights, contact us at <a href="mailto:hello@salidumay.com" data-v-46070531>hello@salidumay.com</a>.</p></section><section class="doc-section" data-v-46070531><h2 data-v-46070531>7. Contact</h2><p data-v-46070531>Questions about this policy? <a href="/contact" data-v-46070531>Reach out to us</a>.</p></section></div></main>',2)),i(t)]))}},h=e(d,[["__scopeId","data-v-46070531"]]);export{h as default};
